package httpapi
import("net/http";"strconv";"strings";"time";"github.com/go-chi/chi/v5";"github.com/google/uuid";"github.com/saurabhkumaryadav2001/recall-api/internal/store")
type input struct{Title string `json:"title"`;Content string `json:"content"`;Tags []string `json:"tags"`;ExpiresAt *time.Time `json:"expires_at"`}
func valid(x input)bool{return strings.TrimSpace(x.Title)!=""&&len(x.Title)<=200&&len(x.Content)<=100000&&len(x.Tags)<=30}
func user(r *http.Request)uuid.UUID{return r.Context().Value(userKey).(uuid.UUID)}
func(a *API)create(w http.ResponseWriter,r *http.Request){var x input;if decode(r,&x)!=nil||!valid(x){fail(w,400,"invalid payload: title 1-200 chars, content <=100k, max 30 tags");return};m,e:=a.s.Create(r.Context(),user(r),store.Memory{Title:strings.TrimSpace(x.Title),Content:x.Content,Tags:x.Tags,ExpiresAt:x.ExpiresAt});if e!=nil{fail(w,500,"create failed");return};write(w,201,m)}
func(a *API)get(w http.ResponseWriter,r *http.Request){id,e:=uuid.Parse(chi.URLParam(r,"id"));if e!=nil{fail(w,400,"invalid id");return};m,e:=a.s.Get(r.Context(),user(r),id);if e!=nil{fail(w,404,"memory not found");return};write(w,200,m)}
func(a *API)list(w http.ResponseWriter,r *http.Request){q:=r.URL.Query();limit,_:=strconv.Atoi(q.Get("limit"));if limit<1||limit>100{limit=20};offset,_:=strconv.Atoi(q.Get("offset"));if offset<0{offset=0};items,total,e:=a.s.List(r.Context(),user(r),strings.TrimSpace(q.Get("q")),strings.TrimSpace(q.Get("tag")),limit,offset);if e!=nil{fail(w,500,"list failed");return};write(w,200,map[string]any{"items":items,"total":total,"limit":limit,"offset":offset})}
func(a *API)update(w http.ResponseWriter,r *http.Request){id,e:=uuid.Parse(chi.URLParam(r,"id"));if e!=nil{fail(w,400,"invalid id");return};var x input;if decode(r,&x)!=nil||!valid(x){fail(w,400,"invalid payload");return};m,e:=a.s.Update(r.Context(),user(r),id,store.Memory{Title:strings.TrimSpace(x.Title),Content:x.Content,Tags:x.Tags,ExpiresAt:x.ExpiresAt});if e!=nil{fail(w,404,"memory not found");return};write(w,200,m)}
func(a *API)delete(w http.ResponseWriter,r *http.Request){id,e:=uuid.Parse(chi.URLParam(r,"id"));if e!=nil{fail(w,400,"invalid id");return};if a.s.Delete(r.Context(),user(r),id)!=nil{fail(w,404,"memory not found");return};w.WriteHeader(204)}
